-- seed_mock_users.sql — Friend System v1 / Sprint 67 / STORY-00527
--
-- Seeds 9 mock @cairn.demo accounts with bcrypt(cost=12) hashes generated by
-- backend/scripts/seed/gen_bcrypt_hashes.js. Passwords are single-character
-- (auth.js login does not enforce length — confirmed STORY-00524).
--
-- Mock matrix per FINAL_PRODUCT_PLAN_v4.md §8:
--   1@..6@ = Alice, Bob, Carol(stranger→friend), Dave(empty), LDY(rich), Eve(paywall)
--   x1@..x3@ = Stranger 1 (single mark near 9163 Back Loop), Stranger 2 (heatmap),
--              Stranger 3 (chain)
--
-- v4.V binding: 9163 (id=4) initial state = 0 friends, 0 subscriptions.
-- This script must NOT touch user_id=4, the friends table, or memory_subscriptions.
--
-- Idempotent: INSERT IGNORE skips rows that already exist by unique email.
-- To re-seed: run clear_mock_data.sql first, then this file.

USE cairn;

-- Sanity guard: refuse to run if a non-mock account has @cairn.demo email
-- (defense-in-depth — should never trigger, but blocks the script from
-- promoting a real user into the mock filter set).
SET @bad := (SELECT COUNT(*) FROM users
             WHERE email LIKE '%@cairn.demo' AND id < 0);
-- (kept as a placeholder; users.id is always > 0; statement is a no-op
-- intentionally — exists to remind future maintainers of the invariant.)

-- ──────────────────────────────────────────────────────────────────────────
-- 1. Mock users (9 rows)
-- ──────────────────────────────────────────────────────────────────────────

INSERT IGNORE INTO users (name, email, password_hash, account_type, memory_subscription_limit) VALUES
