  ('Bob',        '2@cairn.demo',  '$2b$12$cEo7361SzjhgMjZZJZrT3uQK6mO2oShYYA6qzJaIy8w3f8Z08COWm', 'free', 5),
  ('Carol',      '3@cairn.demo',  '$2b$12$.HhlNyLSO8cNnX.0OfewruEWNk4VdvOaQCrt1VYjJzwiCTJb6q1ia', 'free', 5),
  ('Dave',       '4@cairn.demo',  '$2b$12$Ux./ROsRTHTZsY1U0z/laOehoSgCmSdl0IbzqKuMwj4IDtlgoqMJG', 'free', 5),
  ('LDY',        '5@cairn.demo',  '$2b$12$JKAKsFq9LCz4SK0OrsH59OXawsmv05kgBJZcomzv0wweMydBiLi7a', 'free', 5),
  ('Eve',        '6@cairn.demo',  '$2b$12$l3dkUG3ZMPpUwMXlxPrZQeNgQx/Xcro3Wbj0Kx8W702yNu6uXBqV6', 'free', 5),
