  ('Stranger 2', 'x2@cairn.demo', '$2b$12$LuRsfVFOg89IoICAdsnic.0dPbCPPisxcb15wN8pMveF7haZ4d2Xm', 'free', 5),
  ('Stranger 3', 'x3@cairn.demo', '$2b$12$v3d.V5VmHiL2UREmyLCC0e4K9NR.WRRiNLLJze5SJeCUjYLoIj4ce', 'free', 5);

